// Synchronous FIFO — BUG4 before fix (v4).
module fifo(input clk,input rst_n,input wr_en,input rd_en,input [7:0] wr_data,output reg [7:0] rd_data,output reg rd_valid,output full,output empty,output reg overflow,output reg underflow);
reg [3:0]wptr,rptr;reg[4:0]count;reg[7:0]mem[0:15];wire write_accepted=wr_en&&(!full||rd_en);wire read_accepted=rd_en&&!empty;assign full=(count==16);assign empty=(count==0);always@(posedge clk)if(write_accepted)mem[wptr]<=wr_data;always@(posedge clk or negedge rst_n)begin if(!rst_n)begin wptr<=0;rptr<=0;count<=0;rd_data<=0;rd_valid<=0;overflow<=0;underflow<=0;end else begin rd_valid<=read_accepted;overflow<=wr_en&&full&&!rd_en;underflow<=rd_en&&empty&&!wr_en;if(read_accepted)rd_data<=mem[rptr];if(read_accepted)rptr<=rptr+1;if(write_accepted)wptr<=wptr+1;case({write_accepted,read_accepted})2'b10:count<=count+1;2'b01:count<=count-1;default:count<=count;endcase end end endmodule
